use crate::*;
use super::plan::PackPlan;
use base64::{Engine,engine::general_purpose::URL_SAFE_NO_PAD};
use std::io::{Read,Write};
use sha2::{Digest,Sha256};
pub fn create(plan:&PackPlan)->Result<String>{let mut safe=plan.clone();safe.name=ai_diagnose::agent_text(&safe.name);safe.notes.clear();safe.warnings.clear();safe.estimated_download_bytes=0;safe.java="auto".into();safe.localization.note.clear();safe.options.retain(|k,_|["language","renderDistance","simulationDistance","maxFps","guiScale"].contains(&k.as_str()));for r in safe.mods.iter_mut().chain(&mut safe.resource_packs).chain(&mut safe.shaders){r.name=ai_diagnose::agent_text(&r.name);r.reason.clear();}safe.config_patches.retain(|p|p.set.values().all(|v|ai_diagnose::agent_text(&v.to_string())==v.to_string()));safe.check()?;
 let data=serde_json::to_vec(&safe).map_err(err)?;let mut zip=zip::ZipWriter::new(std::io::Cursor::new(Vec::new()));zip.start_file("plan.json",zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated)).map_err(err)?;zip.write_all(&data).map_err(err)?;let bytes=zip.finish().map_err(err)?.into_inner();let checksum=format!("{:x}",Sha256::digest(&bytes));let code=format!("KXL1.{}.{}",URL_SAFE_NO_PAD.encode(bytes),&checksum[..8]);if code.len()>8192{return Err("计划压缩后超过 8 KB，请减少模组或配置补丁。".into());}Ok(code)
}
pub fn decode(code:&str)->Result<PackPlan>{let code=code.trim();if code.len()>8192{return Err("分享码超过 8 KB".into());}let body=code.strip_prefix("KXL1.").ok_or("分享码前缀应为 KXL1")?;let(encoded,checksum)=body.rsplit_once('.').ok_or("分享码缺少校验和")?;let bytes=URL_SAFE_NO_PAD.decode(encoded).map_err(|_|"分享码 base64url 无效")?;let expected=format!("{:x}",Sha256::digest(&bytes));if checksum.len()!=8||checksum!=&expected[..8]{return Err("分享码校验失败，内容可能被篡改或复制不完整。".into());}let mut zip=zip::ZipArchive::new(std::io::Cursor::new(bytes)).map_err(|_|"分享码压缩数据无效")?;if zip.len()!=1{return Err("分享码归档只能包含一个计划".into());}let file=zip.by_name("plan.json").map_err(|_|"分享码缺少计划")?;if file.size()>128*1024{return Err("分享码解压后超过限制".into());}let mut text=String::new();file.take(128*1024+1).read_to_string(&mut text).map_err(|_|"分享码计划不是 UTF-8")?;super::plan::parse(serde_json::from_str(&text).map_err(|_|"分享码计划不是 JSON")?)}
pub async fn preview(core:&Core,code:&str)->Result<Value>{let mut plan=decode(code)?;super::plan::validate(core,&mut plan).await?;Ok(json!({"plan":plan,"importHash":plan.hash()?,"requiresConfirmation":true}))}
#[cfg(test)]mod tests{use super::*;fn plan()->PackPlan{super::super::plan::parse(json!({"version":1,"name":"测试包","minecraft":"1.20.1","loader":{"type":"fabric","version":"0.16.9"},"memoryMb":4096,"notes":["C:\\Users\\private\\secret"],"mods":[]})).unwrap()}
 #[test]fn roundtrip_tamper_and_schema(){let code=create(&plan()).unwrap();let result=decode(&code).unwrap();assert_eq!(result.name,"测试包");assert!(result.notes.is_empty());let mut tampered=code.clone();tampered.pop();tampered.push('f');if tampered==code{tampered.pop();tampered.push('0');}assert!(decode(&tampered).is_err());assert!(decode("KXL2.invalid").is_err());assert!(decode(&"x".repeat(8193)).is_err());assert!(code.len()<=8192);}
}
